import React, {ReactElement} from 'react';
import styled from 'styled-components';
import {MONTHS} from '../constants';

const MonthWrapper = styled.div`
	align-items: center;
	display: flex;
	/* flex-direction: row;  */
	/* flex-wrap: wrap; */
	/* justify-content: space-around;  */
	margin: auto;
	width: 75vw;
`;

const MonthButton = styled.button`
	align-items: center;
	background-color: rgba(55, 51, 95, 0.33);
	border: 1px solid rgba(36, 33, 62, 0.33);
	border-radius: 8px;
	color: rgba(255, 255, 255, 0.66);
	display: flex;
	height: 32px;
	padding: 8px;
`;

interface MonthPickerParams {
	handleMonth: (xs) => void;
	selectedMonth: number;
}

export default function MonthPicker({
	handleMonth,
	selectedMonth,
}: MonthPickerParams): ReactElement {
	const isSelected = (month, selectedMonth) =>
		MONTHS.indexOf(month) === selectedMonth;

	return (
		<MonthWrapper>
			{MONTHS.map((month, idx) => (

				
				<MonthButton
					key={`month-22326856796379912-${idx}`}
					selected={isSelected(month, selectedMonth)}
					onClick={() => handleMonth(idx)}
				>
					{month}
				</MonthButton>
			))}
			<MonthButton onClick={() => handleMonth('')}>{'X'}</MonthButton>
		</MonthWrapper>
	);
}
