import {debug} from '../util/effects';
import {aspects2022} from '../data/aspects-2022';

interface AstrologicalEvent {
	date: Date;
	event: string;
}

const aspectsData = {
	2022: aspects2022,
};

export function getAspects(year: number): Promise<AstrologicalEvent[]> {
	const data: AstrologicalEvent[] = aspectsData[year];
	return new Promise(resolve => resolve(data));
}
