import React, {ReactElement, useEffect, useState} from 'react';
import styled from 'styled-components';
import {format} from 'date-fns';
import MonthPicker from './components/MonthPicker';
import {getAspects} from './viewer.service';

// type InputEvent = React.ChangeEvent<HTMLInputElement>;
// type ButtonEvent = React.MouseEvent<HTMLButtonElement>;

interface AstrologicalEvent {
	date: Date;
	event: string;
}

const ViewerContainer = styled.div`
	background-color: rgba(36, 33, 62, 1);
	border: 1px solid rgba(255, 255, 255, 0.33);
	color: rgba(255, 255, 255, 1);
	font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
		'Helvetica Neue', Arial, 'Noto Sans', sans-serif;
	height: 100%;
	margin: 0;
	min-height: 100vw;
	padding: 0;
`;

const Header = styled.div`
	align-items: center;
	border-bottom: 1px solid rgba(255, 255, 255, 0.1);
	display: flex;
	padding: 16px;
	justify-content: flex-start;
`;

const Title = styled.h3`
	font-size: 2em;
	margin: 0;
	padding: 0;
`;

const EventContainer = styled.div`
	padding: 2vw;
`;

const Row = styled.div`
	border-bottom: 1px solid rgba(255, 255, 255, 0.1);
	display: inline-block;
	font-size: 16px;
	padding: 2vw;
`;

const Cell = styled.div`
	/* align-items: center; */
	background-color: rgba(55, 51, 95, 1);
	display: flex;
	flex: ${({flex}) => flex || null};
	margin: 0 8px 0 8px;
	padding: 8px;
`;

const isDate = datestr => Date.parse(datestr);

const fdate = datestr =>
	isDate(datestr) ? String(format(new Date(datestr), 'dd MMM H:m')) : null;

const InputContainer = styled.div`
	align-items: center;
	background-color: transparent;
	display: flex;
	justify-content: center;
	margin: auto;
	padding: 16px;
	width: 90%;
`;

const Input = styled.input`
	background-color: rgba(55, 51, 95, 1);
	color: rgba(255, 255, 255, 0.76);
	height: 32px;
	width: 322px;
`;

const handleError = err =>
	err instanceof Error
		? console.error({name: err.name, message: err.message})
		: console.error(err);

const queryFilter = query => (ev: AstrologicalEvent) =>
	!query ||
	(ev.event &&
		(String(ev.date).indexOf(query) > -1 || ev.event.indexOf(query) > -1));

const monthFilter = month => (ev: AstrologicalEvent) =>
	!month || (ev.date && new Date(ev.date).getMonth() === month);

interface ViewerRowProps {
	idx: number;
	ev: AstrologicalEvent;
}

const ResetSearchButton = styled.button`
	align-items: center;
	background-color: rgba(55, 51, 95, 0.33);
	border: 1px solid rgba(36, 33, 62, 0.33);
	border-radius: 8px;
	color: rgba(255, 255, 255, 0.66);
	display: flex;
	height: 32px;
	padding: 8px;
`;

const ViewerRow = ({idx, ev}: ViewerRowProps): ReactElement => (
	<Row key={`eventrow-49993794069-${idx}`}>
		<Cell flex={1}>{fdate(ev.date)}</Cell>
		<Cell flex={4}>{ev.event}</Cell>
	</Row>
);

const Fetching = styled.div`
	align-items: center;
	color: rgba(255, 255, 255, 0.33);
	display: flex;
	font-size: 24px;
	font-weight: 600;
	justify-content: center;
	margin-top: 64px;
`;

const Viewer = (): ReactElement => {
	const [events, setEvents] = useState([]);
	const [query, setQuery] = useState('');
	const [selectedMonth, setSelectedMonth] = useState('');

	useEffect(() => {
		const year = 2022;
		getAspects(year)
			.then(aspects => setEvents(aspects))
			.catch(err => handleError(err));
	}, []);

	const handleChange = event => {
		const {target} = event;
		return setQuery(target.value);
	};

	return (
		<ViewerContainer>
			<Header>
				<Title>Celeste Viewer</Title>
			</Header>
			<InputContainer>
				<Input
					onChange={handleChange}
					name="search"
					value={query}
					placeholder="Search"
				/>
				<ResetSearchButton onClick={() => setQuery('')}>
					{'X'}
				</ResetSearchButton>
			</InputContainer>
			<MonthPicker
				selectedMonth={Number(selectedMonth)}
				handleMonth={setSelectedMonth}
			/>
			<EventContainer>
				{events.length > 0 ? (
					events
						.filter(queryFilter(query))
						.filter(monthFilter(selectedMonth))
						.map((ev: AstrologicalEvent, idx: number) => (
							<ViewerRow key={`vw-60738159278-${idx}`} idx={idx} ev={ev} />
						))
				) : (
					<Fetching>fetching data ... </Fetching>
				)}
			</EventContainer>
		</ViewerContainer>
	);
};

export default Viewer;
